/* Developer-tool boundary. Provider/sandbox integration utilities and the internal
   design-system view are developer tooling, not consumer features. They stay hidden
   from the consumer surface unless developer mode is explicitly enabled with
   ?dev=1 in the page URL or enableDevMode() (used by the automated QA harness). */
function isDevMode(){try{if(typeof window!=='undefined'&&window.__PC_DEV===true)return true;if(typeof sessionStorage!=='undefined'&&sessionStorage.getItem('pcDev')==='1')return true;if(typeof location!=='undefined'&&/(?:^|[?&])dev=1(?:&|$)/.test(location.search||''))return true}catch(e){}return false}
function enableDevMode(){try{if(typeof window!=='undefined')window.__PC_DEV=true}catch(e){}try{if(typeof sessionStorage!=='undefined')sessionStorage.setItem('pcDev','1')}catch(e){}if(typeof applyDevVisibility==='function')applyDevVisibility();return true}
function disableDevMode(){try{if(typeof window!=='undefined')window.__PC_DEV=false}catch(e){}try{if(typeof sessionStorage!=='undefined')sessionStorage.removeItem('pcDev')}catch(e){}if(typeof applyDevVisibility==='function')applyDevVisibility();return false}
function applyDevVisibility(){var dev=isDevMode();var ids=['dev-tools','btn-design-system','btn-run-scam-benchmark'];for(var i=0;i<ids.length;i++){var el=typeof document!=='undefined'&&document.getElementById?document.getElementById(ids[i]):null;if(el)el.classList.toggle('hidden',!dev)}if(!dev&&typeof document!=='undefined'&&document.getElementById){var sys=document.getElementById('view-system');var home=document.getElementById('view-home');if(sys&&home&&!sys.classList.contains('hidden')){sys.classList.add('hidden');home.classList.remove('hidden')}}}
