I18N.bn.dataHandlingP='ডিফল্টভাবে তথ্য এই পৃষ্ঠাতেই থাকে। লোকাল এনক্রিপ্ট করা ব্যাকএন্ড কনফিগার করা থাকলেই ঐচ্ছিক কেস সংরক্ষণ চালু হবে; এর জন্য স্পষ্ট সম্মতি দরকার।';
I18N.en.safetyP='Payment-message parsing and screenshot comparison happen locally in your browser. The optional Copilot can send a best-effort redacted summary you type, plus coarse warning/comparison categories, to Cloudflare Workers AI only after explicit consent. This text filter is not guaranteed anonymisation: do not paste a full SMS or include names, phone numbers, account details, payment references, PINs or OTPs. Cloudflare documents zero retention for standard stateless Workers AI inference after processing, but operational metadata may be retained. The free daily allocation is limited and may be exhausted. The app does not control or reverse real payments.'; I18N.bn.safetyP='পেমেন্ট বার্তা বিশ্লেষণ ও স্ক্রিনশট তুলনা আপনার ব্রাউজারেই হয়। ঐচ্ছিক Copilot-এ স্পষ্ট সম্মতি দিলে আপনার লেখা সারাংশের যতটা সম্ভব রেড্যাক্ট করা সংস্করণ এবং সতর্কতা/তুলনার সাধারণ শ্রেণি Cloudflare Workers AI-তে পাঠানো হতে পারে। এই ফিল্টার সম্পূর্ণ পরিচয় গোপন রাখার নিশ্চয়তা নয়: পুরো SMS পেস্ট করবেন না; নাম, ফোন নম্বর, অ্যাকাউন্টের তথ্য, পেমেন্ট রেফারেন্স, PIN বা OTP দেবেন না। Cloudflare জানায় যে সাধারণ stateless Workers AI inference প্রক্রিয়া শেষে গ্রাহকের কনটেন্ট সংরক্ষণ করে না; তবে কার্যক্রম-সংক্রান্ত metadata রাখা হতে পারে। দৈনিক বিনামূল্যের বরাদ্দ সীমিত এবং শেষ হয়ে যেতে পারে। অ্যাপ বাস্তব পেমেন্ট নিয়ন্ত্রণ বা ফেরত দেয় না।';
I18N.en.aiDisclosureP='SMS parsing runs locally. The optional Evidence-to-Action Copilot sends only after you consent, but its free-text note is best-effort redacted and may still reveal information if you include it. Do not paste full SMS, names, phone/account details, payment references, PINs or OTPs. Cloudflare documents zero retention for standard stateless Workers AI inference after processing and says customer content is not used to train models; operational metadata may be retained. The currently documented free allocation is 10,000 Neurons/day and can be exhausted. No AI API key is required; the hosted deployment needs a Cloudflare Pages Workers AI binding. The local offline plan never calls AI.'; I18N.bn.aiDisclosureP='SMS বিশ্লেষণ স্থানীয়ভাবে হয়। ঐচ্ছিক Evidence-to-Action Copilot আপনার সম্মতির পরেই তথ্য পাঠায়, তবে মুক্ত লেখার নোট শুধু যতটা সম্ভব রেড্যাক্ট করা হয়—তথ্য দিলে তা পুরোপুরি গোপন থাকবে এমন নিশ্চয়তা নেই। পুরো SMS, নাম, ফোন/অ্যাকাউন্টের তথ্য, পেমেন্ট রেফারেন্স, PIN বা OTP দেবেন না। Cloudflare জানায় সাধারণ stateless Workers AI inference প্রক্রিয়া শেষে কনটেন্ট সংরক্ষণ করে না এবং গ্রাহকের কনটেন্ট মডেল প্রশিক্ষণে ব্যবহার করে না; তবে কার্যক্রম-সংক্রান্ত metadata রাখা হতে পারে। বর্তমানে নথিভুক্ত বিনামূল্যের বরাদ্দ ১০,০০০ Neurons/দিন, যা শেষ হয়ে যেতে পারে। AI API key প্রয়োজন নেই; hosted deployment-এ Cloudflare Pages Workers AI binding দরকার। স্থানীয় অফলাইন পরিকল্পনা কখনো AI কল করে না।';

function t(k){return (I18N[S.lang]&&I18N[S.lang][k])||I18N.en[k]||k}
function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
function norm(s){return String(s==null?'':s).replace(/[০-৯]/g,function(d){return '০১২৩৪৫৬৭৮৯'.indexOf(d)})}
function digits(s){return norm(s).replace(/\D/g,'')}
/* Canonical BD mobile: returns 11-digit 01XXXXXXXXX or null. Preserves original text elsewhere; this is comparison-only. */
function canonPhone(s){var raw=norm(s==null?'':s).trim();if(!raw)return null;var d=raw.replace(/[\s\-()]/g,'');if(/^\+8801[3-9]\d{8}$/.test(d))return '0'+d.slice(4);if(/^8801[3-9]\d{8}$/.test(d))return '0'+d.slice(3);if(/^01[3-9]\d{8}$/.test(d))return d;return null}
function phoneIssue(s){var raw=norm(s==null?'':s).trim();if(!raw)return 'empty';if(canonPhone(raw))return '';var d=raw.replace(/[\s\-()]/g,'');if(/[^+\d]/.test(d))return 'contains letters or symbols that are not part of a mobile number';if(!/^\+?\d+$/.test(d))return 'unsupported format';return 'not a valid Bangladeshi mobile number (expected 01XXXXXXXXX, 8801XXXXXXXXX or +8801XXXXXXXXX)'}
/* Strict amount: returns integer minor units (paisa) or null. Rejects trailing letters and malformed grouping. */
function amountMinor(s){var raw=norm(s==null?'':s).trim();if(!raw)return null;raw=raw.replace(/^৳\s*/,'').replace(/^(?:Tk\.?|BDT)\s+/i,'').replace(/\s+(?:Tk\.?|BDT)$/i,'').replace(/\s*৳$/,'').trim();if(!raw)return null;if(!/^(\d{1,3}(,\d{3})+|\d+)(\.\d{1,2})?$/.test(raw))return null;var parts=raw.replace(/,/g,'').split('.');var whole=parseInt(parts[0],10);var frac=parts.length>1?parseInt((parts[1]+'0').slice(0,2),10):0;return whole*100+frac}
function numVal(s){var m=amountMinor(s);return m==null?null:m/100}
function mask(n){var canonical=canonPhone(n);var d=canonical||digits(n);if(d.length<7)return n||'—';return d.slice(0,4)+' ••• '+d.slice(-3)}
function fmt(n){var m=amountMinor(n);if(m==null)return'—';var w=Math.floor(m/100),f=m%100;return '৳'+w.toLocaleString('en-IN')+(f?('.'+String(f).padStart(2,'0')):'')}
function diffNote(a,b){a=canonPhone(a)||digits(a);b=canonPhone(b)||digits(b);if(!a||!b||a===b)return null;if(a.length===b.length){var pos=[];for(var i=0;i<a.length;i++)if(a[i]!==b[i])pos.push(i+1);if(pos.length===2&&a[pos[0]-1]===b[pos[1]-1]&&a[pos[1]-1]===b[pos[0]-1])return 'Digits at positions '+pos.join(' & ')+' are swapped.';return 'Differs at position(s): '+pos.join(', ')+'.'}return 'Length differs ('+a.length+' vs '+b.length+' digits).'}

